			case "runs":
				walkSeq(v, "実行")
			case "findings":
				walkSeq(v, "指摘")
			case "plans":
				walkSeq(v, "修正計画")
			case "consequence":
				walkMap(v, "帰結")
			case "premise_check":
				walkMap(v, "根拠の検証")
			case "plan_ref":
