			if len(got) != 2 || !strings.Contains(got[0], "(id 1)") || !strings.Contains(got[1], "(id 3)") {
				t.Fatalf("id 1 と 3 の欠落だけが報告されるはず。出た問題: %v", got)
			}
		})
	}
}

